// RootNavigator.tsx
import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { useAuthStore } from '../stores/authStore';
import AuthStack from './AuthStack';
import MainTabs from './MainTabs';

export type RootStackParamList = {
  AuthStack: undefined;
  MainTabs: undefined;
};

const Stack = createNativeStackNavigator<RootStackParamList>();

export default function RootNavigator() {
  const { isAuthenticated, isLoading, checkAuth } = useAuthStore();

  // Vérifier l'authentification au montage
  useEffect(() => {
    checkAuth();
  }, []);

  if (isLoading) {
    return <SplashScreen />;
  }

  return (
    <NavigationContainer>
      <Stack.Navigator screenOptions={{ headerShown: false }}>
        {isAuthenticated ? (
          <Stack.Screen name="MainTabs" component={MainTabs} />
        ) : (
          <Stack.Screen name="AuthStack" component={AuthStack} />
        )}
      </Stack.Navigator>
    </NavigationContainer>
  );
}
```

On peut passer des paramètres lors de la navigation vers le modal :
```typescript
// Depuis un écran
navigation.navigate('ImagePicker', { 
  onImageSelected: (uri) => setImage(uri),
  allowedTypes: ['image/jpeg', 'image/png'],
  maxSize: 5 * 1024 * 1024
});
```
Dans le modal, on utilise <code>route.params</code> pour récupérer ces paramètres et appeler le callback avec l'image sélectionnée, puis on ferme le modal avec <code>navigation.goBack()</code>.

